"""Per-trial late-row test for an E-C/E-D aggregate (same test as used for E-C auth
and E-PS). For every trial whose second-segment the aggregator flagged, recompute
that segment from the verifier's OWN saved recorder snapshot and the saved anchor
chain with the shipped monitor (scheme from HOMEPROV_SCHEME), and classify:
delta_n > 0 -> rows arrived after the seal (not attributable to the arm);
delta_n <= 0 or segment vanished -> attributable. Read-only; writes one new file.
Usage: late_row_check.py TAG SNAPSHOT_DB CHAIN_JSONL
"""
import collections, importlib.util, json, os, sys

TAG, DB, CHAIN = sys.argv[1:4]
OUT = "/Users/huanbui/Research/HOMEPROV-P13/exp/out"
dst = os.path.join(OUT, "%s_late_row_check.json" % TAG)
if os.path.exists(dst):
    raise SystemExit("refusing to overwrite " + dst)
os.environ.setdefault("HOMEPROV_SCRATCH", os.path.dirname(DB))
spec = importlib.util.spec_from_file_location("m", "/Users/huanbui/Research/HOMEPROV-P13/monitor/monitor.py")
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
agg = json.load(open(os.path.join(OUT, "%s_other_principal_real.json" % TAG)))
first = {}
for line in open(CHAIN):
    if line.strip():
        rec = json.loads(line); p = rec.get("payload") or {}
        for g, segs in (p.get("sealed") or {}).items():
            if isinstance(segs, dict):
                for s, v in segs.items():
                    first.setdefault((g, str(s)), v)
phi = m.commit(m.load(DB))
per_arm = collections.defaultdict(lambda: {"n_valid": 0, "flagged": 0, "late_row": 0, "attributable": 0, "late_detail": []})
for t in agg["trials"]:
    if t.get("err") or t.get("error"):
        continue
    a = per_arm[t["arm"]]; a["n_valid"] += 1
    det = (t.get("_detection") or {}).get("second") or {}
    if not det.get("violation"):
        continue
    a["flagged"] += 1
    seg = det["segment"]; an = first.get(("second", seg)); rc = (phi.get("second") or {}).get(seg)
    dn = None if (an is None or rc is None) else rc["n"] - an["n"]
    if dn is not None and dn > 0:
        a["late_row"] += 1
        a["late_detail"].append({"room": t.get("room"), "trial": t.get("trial"), "segment": seg, "delta_n": dn})
    else:
        a["attributable"] += 1
res = {"tag": TAG, "scheme": m.SCHEME, "snapshot": DB, "chain": CHAIN, "per_arm": per_arm,
       "rule": "delta_n > 0: rows arrived after seal, not attributable; otherwise attributable",
       "how": __doc__}
json.dump(res, open(dst, "w"), indent=1, default=dict)
print(json.dumps({k: {kk: v[kk] for kk in ("n_valid", "flagged", "late_row", "attributable")} for k, v in per_arm.items()}),
      json.dumps({k: v["late_detail"] for k, v in per_arm.items() if v["late_detail"]}))
